// Anchored center: oval thickness when the anchor widget hides itself.
// Lines tagged "Bar.qml:N" are copied from shell/plugins/bar/Bar.qml at 5c7cccbf
// (horizontal bar, barSize 26, Style.space at scale 1).
// Run from a directory holding this file and shell/plugins/bar/BarModel.js:
//   QT_QPA_PLATFORM=offscreen /usr/lib/qt6/bin/qmltestrunner -input tst_hidden_anchor_oval.qml
import QtQuick
import QtTest
import "BarModel.js" as BarModel

Item {
  id: root
  property bool vertical: false
  function space(px) { return Math.max(1, Math.round(px)) }

  // The anchor slot's size: Bar.qml:2063-2064 with a 60x26 widget that can hide.
  Item {
    id: centerAnchorModule
    property bool shown: true
    implicitWidth: shown ? 60 : 0
    implicitHeight: shown ? 26 : 0
    width: implicitWidth
    height: implicitHeight
  }

  // The center host's cross-axis size for every oval (Bar.qml:1594, 1596-1597).
  function centerOvalThickness() {
    var vertical = root.vertical
    var slotCross = vertical ? centerAnchorModule.width : centerAnchorModule.height
    var inset = root.space(4)
    var thickness = Math.max(0, slotCross - inset * 2)
    return thickness
  }

  TestCase {
    name: "HiddenAnchor"

    function test_neighbour_group_keeps_its_oval_when_the_anchor_hides() {
      // Center layout [Q t, anchor t, R t]: with the anchor hidden, Q and R are
      // still one visible run (groupSlots drops hidden slots), so one oval is drawn.
      var spans = BarModel.groupSpans([
        { group: "t", start: 400, end: 437, lead: 7, trail: 0 },
        { group: "t", start: 437, end: 484, lead: 0, trail: 7 }
      ], root.space(7))
      compare(spans.length, 1)
      compare(centerOvalThickness(), 18, "thickness with the anchor shown")
      centerAnchorModule.shown = false
      console.log("thickness with the anchor hidden:", centerOvalThickness())
      verify(centerOvalThickness() > 0, "Q and R keep a visible oval")
    }
  }
}
